package com.alsafa.native4.core;

import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import com.alsafa.native4.sync.SyncOperation;import org.json.JSONArray;import org.json.JSONObject;import java.util.ArrayList;import java.util.List;import java.util.UUID;
/** Online sale: multi-currency deposits/collections, auditable shipping/expenses, and confirmed final-price edits. */
public final class OnlineSaleSettlementStore {
 private final CoreStore.DbProvider provider;private final String deviceId;public OnlineSaleSettlementStore(CoreStore.DbProvider provider,String deviceId){this.provider=provider;this.deviceId=deviceId;}
 public Result create(String saleId,double merchandiseTotal,String saleCurrency,double shippingAmount,String shippingCurrency,boolean buyerPaysShipping,List<SplitPaymentStore.Payment> initialPayments,String shippingPaidStatus,String shippingPaidBy,String shippingAccount)throws Exception{String sid=req(saleId,"الفاتورة"),sc=MoneyRules.currency(saleCurrency),shc=MoneyRules.currency(shippingCurrency);valid(merchandiseTotal,"قيمة المنتجات");valid(shippingAmount,"أجرة الشحن");long now=System.currentTimeMillis();SQLiteDatabase db=provider.db();db.beginTransaction();try{double merchandiseUsd=usd(db,"ONLINE_MERCH",sid,sc,merchandiseTotal,now),customerShippingUsd=buyerPaysShipping?usd(db,"ONLINE_SHIPPING_DUE",sid,shc,shippingAmount,now):0,totalDueUsd=merchandiseUsd+customerShippingUsd;String id="online-"+UUID.randomUUID();ContentValues v=new ContentValues();v.put("settlement_id",id);v.put("sale_id",sid);v.put("merchandise_total",merchandiseTotal);v.put("currency",sc);v.put("shipping_amount",shippingAmount);v.put("shipping_currency",shc);v.put("shipping_payer",buyerPaysShipping?"BUYER":"SELLER");v.put("total_due",totalDueUsd);v.put("paid_total",0);v.put("remaining",totalDueUsd);v.put("created_at",now);v.put("updated_at",now);db.insertOrThrow("online_sale_settlements",null,v);shippingEvent(db,id,shippingAmount,shc,buyerPaysShipping?"BUYER":"SELLER",shippingPaidStatus,shippingPaidBy,shippingAccount,now);List<SplitPaymentStore.Payment> ps=initialPayments==null?new ArrayList<>():initialPayments;double paidUsd=paymentsUsd(db,id,ps,now);if(paidUsd>totalDueUsd+0.01)throw new IllegalArgumentException("الدفعات أكبر من إجمالي المطلوب");JSONArray pj=ps.isEmpty()?new JSONArray():SplitPaymentStore.write(db,"ONLINE_SALE",id,ps,now);updateTotals(db,id,paidUsd,totalDueUsd-paidUsd,now);JSONObject j=payload(id,sid,merchandiseTotal,sc,shippingAmount,shc,buyerPaysShipping,totalDueUsd,paidUsd,totalDueUsd-paidUsd,pj,now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.SALE_UPDATE,sid,j.toString(),deviceId));db.setTransactionSuccessful();return new Result(id,totalDueUsd,paidUsd,totalDueUsd-paidUsd,"USD",0,"NONE");}finally{db.endTransaction();}}
 public Result collect(String settlementId,List<SplitPaymentStore.Payment> payments)throws Exception{String id=req(settlementId,"تسوية بيع الإنترنت");if(payments==null||payments.isEmpty())throw new IllegalArgumentException("أضف دفعة واحدة على الأقل");SQLiteDatabase db=provider.db();db.beginTransaction();try{String saleId;double due,paid;try(Cursor c=db.rawQuery("SELECT sale_id,total_due,paid_total FROM online_sale_settlements WHERE settlement_id=?",new String[]{id})){if(!c.moveToFirst())throw new IllegalArgumentException("تسوية البيع غير موجودة");saleId=c.getString(0);due=c.getDouble(1);paid=c.getDouble(2);}long now=System.currentTimeMillis();double addUsd=paymentsUsd(db,id,payments,now),newPaid=paid+addUsd;if(newPaid>due+0.01)throw new IllegalArgumentException("التحصيل أكبر من المبلغ المتبقي");JSONArray pj=SplitPaymentStore.write(db,"ONLINE_SALE",id,payments,now);double remaining=Math.max(0,due-newPaid);updateTotals(db,id,newPaid,remaining,now);JSONObject j=new JSONObject().put("settlementId",id).put("saleId",saleId).put("payments",pj).put("paidTotalUsd",newPaid).put("remainingUsd",remaining).put("collectedAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.SALE_UPDATE,saleId,j.toString(),deviceId));db.setTransactionSuccessful();return new Result(id,due,newPaid,remaining,"USD",0,"NONE");}finally{db.endTransaction();}}
 /** Explicit delivery-time price edit. Partial collections must use collect() and never become a discount. */
 public Result adjustFinalMerchandisePrice(String settlementId,double finalMerchandiseAmount,boolean confirmed,String reason)throws Exception{String id=req(settlementId,"تسوية بيع الإنترنت");valid(finalMerchandiseAmount,"السعر النهائي");SQLiteDatabase db=provider.db();db.beginTransaction();try{String saleId,cur,shippingCur,payer;double agreed,shipping,paid,oldDue;try(Cursor c=db.rawQuery("SELECT sale_id,merchandise_total,currency,shipping_amount,shipping_currency,shipping_payer,paid_total,total_due FROM online_sale_settlements WHERE settlement_id=?",new String[]{id})){if(!c.moveToFirst())throw new IllegalArgumentException("تسوية البيع غير موجودة");saleId=c.getString(0);agreed=c.getDouble(1);cur=c.getString(2);shipping=c.getDouble(3);shippingCur=c.getString(4);payer=c.getString(5);paid=c.getDouble(6);oldDue=c.getDouble(7);}long now=System.currentTimeMillis();SettlementAdjustmentStore.Result adj=SettlementAdjustmentStore.requireAndWrite(db,"ONLINE_SALE",id,agreed,finalMerchandiseAmount,cur,confirmed,reason,now);double merchandiseUsd=usd(db,"ONLINE_FINAL_MERCH",id+"-"+UUID.randomUUID(),cur,finalMerchandiseAmount,now),shippingUsd="BUYER".equals(payer)?usd(db,"ONLINE_FINAL_SHIPPING",id+"-"+UUID.randomUUID(),shippingCur,shipping,now):0,newDue=merchandiseUsd+shippingUsd;if(paid>newDue+0.01)throw new IllegalArgumentException("السعر النهائي أقل من المبلغ المقبوض بالفعل؛ عالج فرق الإرجاع أولاً");double remaining=Math.max(0,newDue-paid);ContentValues v=new ContentValues();v.put("merchandise_total",finalMerchandiseAmount);v.put("total_due",newDue);v.put("remaining",remaining);v.put("updated_at",now);db.update("online_sale_settlements",v,"settlement_id=?",new String[]{id});JSONObject j=new JSONObject().put("settlementId",id).put("saleId",saleId).put("agreedMerchandiseAmount",agreed).put("finalMerchandiseAmount",finalMerchandiseAmount).put("currency",cur).put("adjustmentKind",adj.kind).put("customerDiscount",adj.discount).put("adjustment",adj.difference).put("oldTotalDueUsd",oldDue).put("totalDueUsd",newDue).put("paidTotalUsd",paid).put("remainingUsd",remaining).put("updatedAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.SALE_UPDATE,saleId,j.toString(),deviceId));db.setTransactionSuccessful();return new Result(id,newDue,paid,remaining,"USD",adj.discount,adj.kind);}finally{db.endTransaction();}}
 public String addExpense(String settlementId,String type,double amount,String currency,String paidBy,String account,String notes)throws Exception{String id=req(settlementId,"تسوية البيع"),cur=MoneyRules.currency(currency),acc=req(account,"الخزنة").toUpperCase();valid(amount,"المصروف");if(amount<=0)throw new IllegalArgumentException("المصروف يجب أن يكون أكبر من صفر");MoneyRules.requireSupported(acc,cur);long now=System.currentTimeMillis();String eid="online-expense-"+UUID.randomUUID();SQLiteDatabase db=provider.db();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("expense_id",eid);v.put("settlement_id",id);v.put("expense_type",req(type,"نوع المصروف"));v.put("amount",amount);v.put("currency",cur);v.put("paid_by",req(paidBy,"من دفع المصروف"));v.put("account",acc);v.put("notes",notes==null?"":notes.trim());v.put("created_at",now);db.insertOrThrow("online_order_expenses",null,v);ContentValues cm=new ContentValues();cm.put("move_id","cash-"+UUID.randomUUID());cm.put("source_type","ONLINE_EXPENSE");cm.put("source_id",eid);cm.put("direction","OUT");cm.put("amount",amount);cm.put("currency",cur);cm.put("payment_method","EXPENSE");cm.put("drawer",acc);cm.put("created_at",now);db.insertOrThrow("cash_moves",null,cm);FxSnapshotStore.capture(db,"ONLINE_EXPENSE",eid,cur,amount,now);db.setTransactionSuccessful();return eid;}finally{db.endTransaction();}}
 private static void shippingEvent(SQLiteDatabase db,String id,double amount,String cur,String responsibility,String status,String paidBy,String account,long now){String st=req(status,"حالة دفع الشحن").toUpperCase(),pb=req(paidBy,"من دفع الشحن").toUpperCase(),acc=account==null?"":account.trim().toUpperCase();if(!acc.isEmpty())MoneyRules.requireSupported(acc,cur);ContentValues v=new ContentValues();v.put("event_id","shipping-"+UUID.randomUUID());v.put("settlement_id",id);v.put("shipping_amount",amount);v.put("currency",cur);v.put("responsibility",responsibility);v.put("paid_status",st);v.put("paid_by",pb);v.put("account",acc);v.put("created_at",now);db.insertOrThrow("online_shipping_events",null,v);}
 private static double paymentsUsd(SQLiteDatabase db,String id,List<SplitPaymentStore.Payment> ps,long now){double sum=0;for(SplitPaymentStore.Payment p:ps){if(p==null||!Double.isFinite(p.amount)||p.amount<=0)throw new IllegalArgumentException("مبلغ الدفعة غير صالح");sum+=usd(db,"ONLINE_PAYMENT_CHECK",id+"-"+UUID.randomUUID(),MoneyRules.currency(p.currency),p.amount,now);}return sum;}
 private static double usd(SQLiteDatabase db,String type,String id,String cur,double amount,long now){return FxSnapshotStore.capture(db,type,id,cur,amount,now).usdAmount;}
 private static void updateTotals(SQLiteDatabase db,String id,double paid,double remaining,long now){ContentValues v=new ContentValues();v.put("paid_total",paid);v.put("remaining",remaining);v.put("updated_at",now);db.update("online_sale_settlements",v,"settlement_id=?",new String[]{id});}
 private static JSONObject payload(String id,String sale,double merchandise,String currency,double shipping,String shippingCurrency,boolean buyer,double due,double paid,double remaining,JSONArray payments,long now)throws Exception{return new JSONObject().put("settlementId",id).put("saleId",sale).put("saleChannel","ONLINE").put("merchandiseTotal",merchandise).put("currency",currency).put("shippingAmount",shipping).put("shippingCurrency",shippingCurrency).put("shippingPayer",buyer?"BUYER":"SELLER").put("totalDueUsd",due).put("paidTotalUsd",paid).put("remainingUsd",remaining).put("payments",payments).put("updatedAt",now);}
 private static void valid(double v,String l){if(!Double.isFinite(v)||v<0)throw new IllegalArgumentException(l+" غير صالح");}private static String req(String v,String l){String s=v==null?"":v.trim();if(s.isEmpty())throw new IllegalArgumentException(l+" مطلوب");return s;}
 public static final class Result{public final String settlementId,reportingCurrency,adjustmentKind;public final double totalDueUsd,paidTotalUsd,remainingUsd,customerDiscount;Result(String id,double due,double paid,double rem,String c,double disc,String kind){settlementId=id;totalDueUsd=due;paidTotalUsd=paid;remainingUsd=rem;reportingCurrency=c;customerDiscount=disc;adjustmentKind=kind;}}
}
